import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.BxCN1dRw.js";const b=JSON.parse('{"title":"跟做：负载、饱和与长测报告","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/load-reports"},"headers":[],"relativePath":"tutorials/load-reports.md","filePath":"tutorials/load-reports.md"}'),s={name:"tutorials/load-reports.md"};function o(i,t,c,l,n,h){return a(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="跟做-负载、饱和与长测报告" tabindex="-1">跟做：负载、饱和与长测报告 <a class="header-anchor" href="#跟做-负载、饱和与长测报告" aria-label="Permalink to &quot;跟做：负载、饱和与长测报告&quot;">​</a></h1><p><a href="./perf-gates">上一章</a>的<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/CONTEXT.md" target="_blank" rel="noreferrer">性能合同</a>管确定性预算：往返次数、行数、字节，CI 每次都验收。本章补上<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">规范 §17.3</a> 的另一半——墙钟行为：常规负载什么样子、并发到哪里出现饱和点、长时间运行队列与内存是否稳定。这类数字天生跨机器抖动，所以模板给它们立了三条规矩：<strong>负载只打受控栈，绝不指向你已有的数据库</strong>；<strong>报告在夜跑与版本发布时产出，永远不进普通 PR 的门禁</strong>；<strong>限流不是错误</strong>——429 与 <code>rate_limit.exceeded</code> 是文档化的背压合同，报告单列为“预期限流”，与真实业务错误分开呈现。</p><h2 id="_1-受控负载栈-压的是临时栈-不是你的数据" tabindex="-1">1. 受控负载栈：压的是临时栈，不是你的数据 <a class="header-anchor" href="#_1-受控负载栈-压的是临时栈-不是你的数据" aria-label="Permalink to &quot;1. 受控负载栈：压的是临时栈，不是你的数据&quot;">​</a></h2><p>每条负载命令都先由 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/stack.mjs" target="_blank" rel="noreferrer">stack.mjs</a> 拉起一个全新的<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/CONTEXT.md" target="_blank" rel="noreferrer">受控负载栈</a>：用仓库里那份开发 compose 文件，但以独立项目名 <code>saas-perf</code> 启动，每个服务每次现场分配空闲端口、卷随项目隔离——你的开发栈（<code>axum-saas-template</code> 项目）与任何生产部署都不可能被碰到，连数据目录都不共享。API 与 Worker 用宿主机上的 release 构建运行，因为容量读数应该度量的是产品本身的速度。命令结束（无论成败）时 <code>down -v</code> 连卷销毁，栈从不存在“跑完还留着数据”的状态；要事后排查可用 <code>PERF_STACK_KEEP=1</code> 保留，脚本会打印销毁命令。</p><p>栈上限流被放宽到每分钟一百万次——容量读数要度量的是应用，不是本地默认限流（注册每分钟 20 次会把播种循环淹死）。放宽的还有 Redis 降级时的本地兜底限额：负载压上来时 Redis 计数偶尔错过预算，限流器会退化到按对端计数的本地兜底桶，兜底若保持默认的每分钟 120 次，整个窗口会变成 429 风暴而不是容量读数。场景代码仍然逐请求把 429 分类计数，所以哪天你把限流调回真实值重跑，报告依旧诚实。</p><h2 id="_2-数据与场景-全部走公开接口" tabindex="-1">2. 数据与场景：全部走公开接口 <a class="header-anchor" href="#_2-数据与场景-全部走公开接口" aria-label="Permalink to &quot;2. 数据与场景：全部走公开接口&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/fixtures.mjs" target="_blank" rel="noreferrer">fixtures.mjs</a> 按可配置规模播种数据集，全程走注册、建文档、传附件的公开 HTTP 接口，从不直接写数据库；规模档位与实际播种数量写进报告的 fixtures 元数据，让每个数字都能对上“它是在多大的数据上测出来的”。</p><table tabindex="0"><thead><tr><th>场景</th><th>文件</th><th>做什么</th><th>默认档</th></tr></thead><tbody><tr><td><code>load</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/k6/load.js" target="_blank" rel="noreferrer">k6/load.js</a></td><td>常规负载：登录后的读多写少混合（列表 / 读文档 / 偶尔创建），恒定并发</td><td>4 VU × 60s</td></tr><tr><td><code>saturation</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/k6/saturation.js" target="_blank" rel="noreferrer">k6/saturation.js</a></td><td>只读混合的固定并发阶梯，由运行器逐档执行再合并成吞吐-并发曲线</td><td>1→32 VU × 20s</td></tr><tr><td><code>trajectory</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/k6/trajectory.js" target="_blank" rel="noreferrer">k6/trajectory.js</a></td><td>真实用户轨迹：注册→登录→创建→编辑冲突（409 后重试）→附件上传/下载→导出申请→等 Worker→下载导出→通知</td><td>2 VU × 60s</td></tr><tr><td><code>soak</code></td><td><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/k6/soak.js" target="_blank" rel="noreferrer">k6/soak.js</a></td><td>低并发长跑：编辑、附件、导出申请循环，观察队列排空与内存走势</td><td>2 VU × 600s</td></tr></tbody></table><p>每个 VU 在首个迭代登录一次并复用会话；写请求带随机幂等键，与其他客户端没有任何区别。k6 缺失时命令打印安装指引退出，不会假装跑过；仓库里的报告以 k6 v2.3.0 产出。</p><h2 id="_3-报告里有什么、怎么读" tabindex="-1">3. 报告里有什么、怎么读 <a class="header-anchor" href="#_3-报告里有什么、怎么读" aria-label="Permalink to &quot;3. 报告里有什么、怎么读&quot;">​</a></h2><p>每条命令写 <code>.scratch/perf/&lt;场景&gt;-report.json</code>，四块内容：</p><ul><li><strong>k6 指标</strong>：吞吐（req/s）、<code>http_req_duration</code> 的 P50/P95/P99、检查失败率、<code>expected_throttles</code> 与 <code>business_errors</code> 计数器——业务错误还拆出 <code>business_error_4xx</code> / <code>business_error_5xx</code> 两列，4xx 波是回归、5xx 波是容量降级，一眼可辨。读稳态报告先看业务错误——一条把业务错误刷爆的运行不是读数，是故障记录。</li><li><strong>饱和点读法</strong>（saturation 报告）：吞吐随并发上升，到某一档后不再增长、错误开始出现——曲线的转折就是饱和点。报告给出 <code>plateauFromVUs</code> 提示（吞吐达到最佳档 90% 的最小并发档），它只是阅读辅助，不构成任何断言。稳态场景（load / trajectory / soak）带 <code>business_errors</code> 计数轨道，把刷爆错误的运行挡在门外；饱和阶梯故意越过容量，顶端档出现错误正是要观察的信号，所以它没有这条轨道——错误拆成 4xx/5xx 记进报告，而不是让命令失败。</li><li><strong>栈采样</strong>：场景运行期间每 2 秒采样一次的连接池占用（<code>pg_stat_activity</code>）、任务队列深度（按 <code>saas_core.jobs</code> 状态分组）与 api/worker 进程 RSS，聚合出 min/avg/max，原始采样序列一并保留——soak 的价值就在这条时间线上。</li><li><strong>环境元数据</strong>：规模档、VU 数、时长、限流配置、fixtures 实况——报告必须自带复现条件。</li></ul><h2 id="_4-在哪跑、怎么调" tabindex="-1">4. 在哪跑、怎么调 <a class="header-anchor" href="#_4-在哪跑、怎么调" aria-label="Permalink to &quot;4. 在哪跑、怎么调&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 或 perf-saturation / perf-trajectory / perf-soak</span></span></code></pre></div><p>前置工具只有 k6。规模与时长全部由环境变量调节，命令本身不带参数：</p><table tabindex="0"><thead><tr><th>变量</th><th>默认</th><th>作用</th></tr></thead><tbody><tr><td><code>PERF_SCALE</code></td><td><code>sm</code></td><td>数据规模档（sm / md / lg）</td></tr><tr><td><code>PERF_USERS</code> / <code>PERF_DOCS_PER_USER</code></td><td>规模档决定</td><td>精确覆盖播种数量</td></tr><tr><td><code>PERF_VUS</code></td><td>场景决定</td><td>并发虚拟用户数</td></tr><tr><td><code>PERF_DURATION</code></td><td>场景决定</td><td>时长（秒；saturation 用 <code>PERF_STEP_SECS</code>）</td></tr><tr><td><code>PERF_STEPS</code></td><td><code>1,4,8,16,32</code></td><td>饱和阶梯的并发档位</td></tr><tr><td><code>PERF_STEP_SECS</code></td><td><code>20</code></td><td>饱和阶梯每档时长（秒）</td></tr><tr><td><code>PERF_SAMPLE_MS</code></td><td><code>2000</code></td><td>栈采样间隔（连接池 / 队列 / RSS，毫秒）</td></tr><tr><td><code>PERF_STACK_KEEP</code></td><td>未设</td><td>设为 <code>1</code> 保留栈供排查</td></tr></tbody></table><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/.github/workflows/perf-nightly.yml" target="_blank" rel="noreferrer">perf-nightly.yml</a> 在夜跑（与手动触发）时跑全套：装 checksum 校验过的 k6、跑 load / 饱和阶梯（截短）/ trajectory / 限时 soak，报告作为 artifact 保留 30 天。普通 PR 永远不跑它们——PR 上只有<a href="./perf-gates">上一章的确定性门禁</a>。</p><h2 id="_5-首份实测与删例后的去处" tabindex="-1">5. 首份实测与删例后的去处 <a class="header-anchor" href="#_5-首份实测与删例后的去处" aria-label="Permalink to &quot;5. 首份实测与删例后的去处&quot;">​</a></h2><p>首份实测留档如下（本地 x86_64 WSL2，默认规模档 6 用户 × 8 文档；数字随机器、邻居负载与数据分布浮动——留档的意义是给后来者一个可对比的起点，不是任何机器上的承诺）：</p><table tabindex="0"><thead><tr><th>场景</th><th>配置（默认档）</th><th>吞吐</th><th>P50 / P95 / P99</th><th>业务错误</th></tr></thead><tbody><tr><td>load</td><td>4 VU × 60s</td><td>308.1 req/s（18,480 请求）</td><td>10.5 / 28.3 / 38.1 ms</td><td>0</td></tr><tr><td>saturation</td><td>1→16 VU × 15s</td><td>131.9 → 270.9 → 270.2 → 177.4 req/s</td><td>p95: 10.3 → 23.5 → 54.8 → 155.2 ms</td><td>8 与 16 VU 档各 23 / 29 次，全为 5xx</td></tr><tr><td>trajectory</td><td>2 VU × 60s</td><td>46.3 req/s（164 次完整旅程）</td><td>p95 34.8 ms</td><td>0</td></tr><tr><td>soak</td><td>2 VU × 300s</td><td>9.4 req/s（2,832 请求）</td><td>20.5 / — / 24.0 ms</td><td>0</td></tr></tbody></table><p>按 §3 的读法：饱和曲线在 4 VU 档进入最佳吞吐（270.9 req/s）的九成以上，<code>plateauFromVUs=4</code>；再往上并发，吞吐回落而 p95 拉长近六倍，8/16 VU 档开始出现 5xx——这就是这条曲线要观察的容量降级信号，报告照实记录而不判定失败。soak 的 151 个采样点才是长测的价值所在：api 进程 RSS 全程稳定在 61.9–62.5 MiB、worker 在 17.0–17.3 MiB，连接池占用稳定在 3–7，导出队列最深仅 2、即刻排空——五分钟长测里看不到泄漏或积压的迹象。k6 v2.3.0；完整报告（含原始采样序列与环境元数据）由命令写入 <code>.scratch/perf/*-report.json</code>，不入版本库。</p><p>删例边界与<a href="./perf-gates">性能门禁</a>同一条线：四个场景与 fixtures 以知识库示例的端点为载体，示例移除后 <code>just perf-load</code> 等命令会在开工前诚实说明并退出。场景脚本与 fixtures 留在仓库里作骨架模板，但真正业务无关、删例后照常可用的是<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/stack.mjs" target="_blank" rel="noreferrer">受控负载栈</a>、采样器与报告结构（<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/scripts/perf/report.mjs" target="_blank" rel="noreferrer">report.mjs</a>）。为自己的业务建模时：场景换成你的热路径接口，fixtures 换成你的领域数据，“限流单列、饱和点只记录”的规矩原样保留。</p><p>关于微基准的一次成文决定：本票评估过给导出渲染（工作区唯一的纯计算热点）挂 Criterion。它不在热路径上——导出是异步任务——而 criterion 会进入每次 <code>clippy --all-targets</code> 的编译成本。结论是不引入；规范要的负载证据由场景报告提供，若未来出现真正的热路径纯函数，再按同一节流程补上。</p><h2 id="_6-运行本章检查" tabindex="-1">6. 运行本章检查 <a class="header-anchor" href="#_6-运行本章检查" aria-label="Permalink to &quot;6. 运行本章检查&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> perf-load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 任一负载命令跑通即验证本章链路</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 主门禁不包含负载场景——这正是设计</span></span></code></pre></div><p>示例移除后的行为由<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/tests/tooling/example-remove.test.mjs" target="_blank" rel="noreferrer">移除工具测试</a>与删例 CI 验收覆盖；负载命令的诚实退出与 <code>production-smoke</code> 同一套模式。</p><hr><p>源码版本：<code>0b53e60ef0f0</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/0b53e60ef0f0991768399aec41a29b2bdd00ddaa/docs/tutorials/25-load-reports.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,28)])])}const u=e(s,[["render",o]]);export{b as __pageData,u as default};
